    stage: str
    epoch: int
    status: str
    attempt_ref: str
    attempt_generation: int
    root_session_ref: str
    native_session_ref: str | None
    runtime_binding: (
        IdeaRuntimeBinding
        | PlanRuntimeBinding
        | BundleRuntimeBinding
        | ReasoningRuntimeBinding
    )
